import sys

def solve():
    # Read all input from stdin
    input_data = sys.stdin.read().split()

    if not input_data:
        return

    iterator = iter(input_data)

    try:
        n_str = next(iterator)
        N = int(n_str)

        # Read A
        A = []
        for _ in range(N):
            A.append(int(next(iterator)))
    except StopIteration:
        return

    # Dictionary to store the last seen index of each value
    last_pos = {}

    # Initialize min_len to infinity
    min_len = float('inf')

    # Iterate through the array
    for i, val in enumerate(A):
        # If the value has been seen before
        if val in last_pos:
            # Calculate the length of the subarray between the last occurrence and current
            length = i - last_pos[val] + 1
            # Update the minimum length found so far
            if length < min_len:
                min_len = length

        # Update the last position of the current value
        last_pos[val] = i

    if min_len == float('inf'):
        print("-1")
    else:
        print(min_len)

if __name__ == '__main__':
