class Solution:
    def minCost(self, n: int, cost: List[List[int]]) -> int:
        # dp[c0][c1] stores the minimum cost for the current pair of houses
        # c0 is the color of the house at index i
        # c1 is the color of the house at index n - 1 - i
        # We iterate i from 0 to n/2 - 1

        # Initialize dp for the first pair (i = 0)
        # Houses 0 and n-1
        dp = {}
        for c0 in range(3):
            for c1 in range(3):
                if c0 != c1:
                    dp[(c0, c1)] = cost[0][c0] + cost[n-1][c1]

        # Iterate through the remaining pairs
        for i in range(1, n // 2):
            new_dp = {}
            # Houses i and n-1-i
            for c0 in range(3):
                for c1 in range(3):
                    if c0 == c1:
                        continue

                    # Find the minimum cost from the previous pair
                    # Previous pair was i-1 and n-1-(i-1) = n-i
                    # Constraints: c0 != c_{i-1} and c1 != c_{n-1-(i-1)}

                    min_prev = float('inf')
                    for prev_c0 in range(3):
                        for prev_c1 in range(3):
                            if prev_c0 == prev_c1:
                                continue
                            if c0 != prev_c0 and c1 != prev_c1:
                                min_prev = min(min_prev, dp[(prev_c0, prev_c1)])

                    if min_prev != float('inf'):
                        new_dp[(c0, c1)] = min_prev + cost[i][c0] + cost[n-1-i][c1]

            dp = new_dp

        # The result is the minimum cost of the last pair
        return min(dp.values())

