class Solution:
    def maxDifference(self, s: str) -> int:
        # Count the frequency of each character in the string
        freq = {}
        for char in s:
            freq[char] = freq.get(char, 0) + 1

        # Separate the frequencies into odd and even lists
        odd_frequencies = []
        even_frequencies = []

        for count in freq.values():
            if count % 2 == 1:
                odd_frequencies.append(count)
            else:
                even_frequencies.append(count)

        # Find the maximum odd frequency and minimum even frequency
        # The problem guarantees that both lists are non-empty based on constraints
        max_odd = max(odd_frequencies)
        min_even = min(even_frequencies)

        # Return the maximum difference
        return max_odd - min_even

class Solution:
    def hasSpecialSubstring(self, s: str, k: int) -> bool:
        n = len(s)
        # Iterate through all possible substrings of length k
        for i in range(n - k + 1):
            # Check if the substring s[i:i+k] consists of only one distinct character
            # We assume s[i] is the character. Check all subsequent characters in the range.
            char = s[i]
            is_uniform = True
            for j in range(i + 1, i + k):
                if s[j] != char:
                    is_uniform = False
                    break

            if not is_uniform:
                continue

            # Check boundary conditions
            # If there is a character immediately before the substring, it must be different.
            if i > 0 and s[i-1] == char:
                continue
            # If there is a character immediately after the substring, it must be different.
            if i + k < n and s[i+k] == char:
                continue

            # If all conditions are met, return True
            return True

        # If no such substring is found, return False
        return False

