class Solution:
    def largestInteger(self, nums: List[int], k: int) -> int:
        # Dictionary to store the frequency of each number across all subarrays
        counts = {}
        n = len(nums)

        # Iterate through all possible subarrays of size k
        # There are n - k + 1 such subarrays
        for i in range(n - k + 1):
            # Get the unique elements in the current subarray
            # Using a set to identify unique numbers in the subarray nums[i : i+k]
            unique_elements = set(nums[i : i + k])

            # For each unique number in the subarray, increment its count
            for num in unique_elements:
                if num in counts:
                    counts[num] += 1
                else:
                    counts[num] = 1

        # Identify numbers that appear in exactly one subarray
        almost_missing = [num for num, count in counts.items() if count == 1]

        # Return the largest almost missing integer, or -1 if none exists
        if not almost_missing:
            return -1
        return max(almost_missing)

