class Solution:
    def numberOfComponents(self, properties: List[List[int]], k: int) -> int:
        n = len(properties)

        # Build adjacency list
        adj = [[] for _ in range(n)]

        for i in range(n):
            for j in range(i + 1, n):
                # Count distinct integers common to both arrays
                common = set(properties[i]) & set(properties[j])
                if len(common) >= k:
                    adj[i].append(j)
                    adj[j].append(i)

        # Count connected components using BFS
        visited = [False] * n
        components = 0

        for i in range(n):
            if not visited[i]:
                components += 1
                # Start BFS
                stack = [i]
                visited[i] = True
                while stack:
                    node = stack.pop()
                    for neighbor in adj[node]:
                        if not visited[neighbor]:
                            visited[neighbor] = True
                            stack.append(neighbor)

        return components

