class Solution:
    def maxAdjacentDistance(self, nums: List[int]) -> int:
        max_diff = 0
        n = len(nums)
        # Iterate through each element in the circular array
        for i in range(n):
            # Calculate the absolute difference between the current element and its next neighbor.
            # The modulo operator (i + 1) % n handles the circular wrap-around (last element connects to first).
            diff = abs(nums[i] - nums[(i + 1) % n])
            if diff > max_diff:
                max_diff = diff
        return max_diff

class Solution:
    def findValidPair(self, s: str) -> str:
        # Count the frequency of each digit in the string
        from collections import Counter
        count = Counter(s)

        # Iterate through adjacent pairs from left to right
        for i in range(len(s) - 1):
            first_digit = int(s[i])
            second_digit = int(s[i+1])

            # First digit must not equal second digit
            if first_digit != second_digit:
                # Check if each digit appears in s exactly as many times as its numeric value
                if count[first_digit] == first_digit and count[second_digit] == second_digit:
                    return s[i] + s[i+1]

        # No valid pair found
        return ""

