class Solution:
    def sumOfGoodNumbers(self, nums: List[int], k: int) -> int:
        total_sum = 0
        n = len(nums)

        for i in range(n):
            # Initialize is_good as True
            is_good = True

            # Check if nums[i] is strictly greater than nums[i-k]
            # If i >= k, index i-k exists.
            if i >= k:
                if nums[i] <= nums[i - k]:
                    is_good = False

            # Check if nums[i] is strictly greater than nums[i+k]
            # If i + k < n, index i+k exists.
            if i + k < n:
                if nums[i] <= nums[i + k]:
                    is_good = False

            if is_good:
                total_sum += nums[i]

        return total_sum

