import itertools

class Solution:
    def totalNumbers(self, digits: List[int]) -> int:
        distinct_numbers = set()

        # Iterate through all permutations of length 3 from the input digits.
        # itertools.permutations handles the "no replacement" constraint naturally by 
        # generating permutations based on indices, which handles the "copy of digit" rule.
        for p in itertools.permutations(digits, 3):
            # Check for leading zero: The first digit cannot be 0.
            if p[0] == 0:
                continue

            # Check if the number is even. A number is even if its last digit is even.
            # We construct the number to ensure we are counting distinct 3-digit numbers.
            # num = p[0] * 100 + p[1] * 10 + p[2]
            # Alternatively, since 100 and 10 are even, num % 2 == p[2] % 2.
            if p[2] % 2 == 0:
                num = p[0] * 100 + p[1] * 10 + p[2]
                distinct_numbers.add(num)

        return len(distinct_numbers)
